css:
.tf-title { margin: 0 0 12px; }
.tf-tab { margin: 16px 0 8px; }
.tf-section { margin: 16px 0 6px; padding-bottom: 4px; border-bottom: 1px solid rgba(0, 0, 0, 0.2); }
.tf-grid { width: 100%; border-collapse: collapse; }
.tf-grid > tbody > tr > td { vertical-align: top; padding: 0 12px 0 0; }
.tf-fields { width: 100%; border-collapse: collapse; }
.tf-fields th, .tf-fields td { text-align: left; vertical-align: top; padding: 5px 8px 5px 0; page-break-inside: avoid; }
.tf-fields td { white-space: pre-line; }
.tf-fields th { width: 40%; font-weight: 600; }

html:
{% set form = task_print_layout(doc) %}
{% for tab in form.tabs or [{"label": "", "sections": []}] %}
<div class="page-break">
<div {% if print_settings.repeat_header_footer %}id="header-html" class="hidden-pdf"{% endif %}>
{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}
</div>
{% if loop.first %}<h2 class="tf-title">{{ form.title | e }}</h2>{% endif %}
{% if tab.label %}<h3 class="tf-tab">{{ tab.label | e }}</h3>{% endif %}
{% for section in tab.sections %}
{% if section.label %}<h4 class="tf-section">{{ section.label | e }}</h4>{% endif %}
<table class="tf-grid"><tr>
{% for column in section.columns %}
<td style="width: {{ (100 / section.columns | length) | int }}%">
<table class="tf-fields">
{% for f in column %}<tr><th>{{ f.label | e }}</th><td>{{ f.value | e }}</td></tr>{% endfor %}
</table>
</td>
{% endfor %}
</tr></table>
{% endfor %}
<div {% if print_settings.repeat_header_footer %}id="footer-html" class="visible-pdf"{% endif %}>
{% if not no_letterhead and footer %}<div class="letter-head-footer">{{ footer }}</div>{% endif %}
</div>
</div>
{% endfor %}
